insert into public.items (id, block, demand, options, explain) values ('r2-fizz-01', 'R2', 0, '[{"right":false,"trap":"yes-no-question","b":null,"why":"This asks about the whole world, and you can answer it with just yes or no."},{"right":false,"trap":"yes-no-question","b":null,"why":"This starts with Do, so the answer is just yes or no. Taste tells us little about the issue."},{"right":false,"trap":"vague-question","b":null,"why":"This is one small number from one afternoon. It is too narrow to show the real issue."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'The best question starts with How, names the place, the issue and who is affected, and needs research to answer. Questions that start with Are or Do can be answered with just yes or no.');
insert into public.items (id, block, demand, options, explain) values ('e1-zap-01', 'E1', 0, '[{"right":false,"trap":"vested-interest-missed","b":null,"why":"The advert mentions tests, but companies don''t make adverts to help you pass. What does ZapFizz get?"},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"author-not-checked","b":null,"why":"There is no research in the advert. A drinks company made it, not scientists."},{"right":false,"trap":"author-not-checked","b":null,"why":"The advert says nothing bad about sugar. A company would not warn you about its own drink."}]'::jsonb, 'ZapFizz makes and sells the drink, so the advert''s purpose is to sell. That is why it only shows good things.');
insert into public.items (id, block, demand, options, explain) values ('e1-lina-01', 'E1', 0, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"emotive-hook","b":null,"why":"Water is not in the post. Read to the end: what does she want from you?"},{"right":false,"trap":"emotive-hook","b":null,"why":"Lina never tells you to see a doctor. Read the last line of the post again."},{"right":false,"trap":"author-not-checked","b":null,"why":"The post has no science report. Look at what her link is for."}]'::jsonb, 'The post ends with an advert for her plan. A source that sells something has a reason to exaggerate.');
insert into public.items (id, block, demand, options, explain) values ('e1-report-01', 'E1', 1, '[{"right":false,"trap":"author-not-checked","b":null,"why":"It suggests free water. Would a company that sells sugary drinks ask for that?"},{"right":false,"trap":"author-not-checked","b":null,"why":"A short homework project could not ask 2,400 students. Check the name of who made it."},{"right":false,"trap":"author-not-checked","b":"E1","why":"The report does not sell anything. Check the name of the group that made it."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'The Health Service made it to learn about students'' health. It sells nothing, which is one reason it is more credible.');
insert into public.items (id, block, demand, options, explain) values ('e2-news-01', 'E2', 0, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"author-not-checked","b":null,"why":"Shop owners know about sales, not health. And check the date."},{"right":false,"trap":"old-source","b":null,"why":"The article is about the past. Check when it was written before you say ''now''."},{"right":false,"trap":"old-source","b":null,"why":"Even a checked fact can go out of date. Look at the date on the article."}]'::jsonb, 'Currency is the C in CRAAP. An article from 2009 tells us about the past, not about students today.');
insert into public.items (id, block, demand, options, explain) values ('e2-report-01', 'E2', 1, '[{"right":false,"trap":"emotive-hook","b":null,"why":"A source is not strong just because it agrees with you."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"author-not-checked","b":null,"why":"Easy to read does not mean strong. Think about how much evidence it has and who made it."},{"right":false,"trap":"all-or-nothing","b":null,"why":"Numbers can be wrong or made up. A source is strong because of who made it and how."}]'::jsonb, 'A large survey by a health organisation that explains its method is accurate and has authority. Numbers alone don''t make a source true.');
insert into public.items (id, block, demand, options, explain) values ('e2-nurse-01', 'E2', 2, '[{"right":false,"trap":"all-or-nothing","b":null,"why":"Experts can be wrong too. She says herself that she has not counted carefully."},{"right":false,"trap":"anecdote-as-proof","b":"E1","why":"She sees a lot, but she says she has not counted. Seeing is not the same as measuring."},{"right":false,"trap":"all-or-nothing","b":null,"why":"One person''s view can still be a useful clue. It just needs more evidence with it."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'Good judgements are often ''partly''. Her experience is useful local evidence, but without counting it is not proof.');
insert into public.items (id, block, demand, options, explain) values ('e3-lina-01', 'E3', 0, '[{"right":false,"trap":"emotive-hook","b":null,"why":"This is the name of her product. It is not chosen to stir up your feelings."},{"right":false,"trap":"emotive-hook","b":null,"why":"These words just say what she did. They are calm, not emotional."},{"right":false,"trap":"emotive-hook","b":null,"why":"This just tells you where the link is. It does not try to make you feel anything."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'Words like POISON, capitals and emojis try to scare you. Feelings are not evidence.');
insert into public.items (id, block, demand, options, explain) values ('e3-zap-01', 'E3', 1, '[{"right":false,"trap":"claim-no-evidence","b":null,"why":"The advert does not compare ZapFizz with any other drink."},{"right":false,"trap":"emotive-hook","b":null,"why":"The advert never says how much sugar is in the can."},{"right":false,"trap":"emotive-hook","b":null,"why":"The advert gives no science at all. ''Feel the energy!'' is not evidence."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'It is a feeling, not a fact. Adverts use emotive phrases to make you want the product.');
insert into public.items (id, block, demand, options, explain) values ('e3-study-01', 'E3', 2, '[{"right":false,"trap":"vested-interest-missed","b":"E1","why":"Scientific studies can be biased too. Read the small print."},{"right":false,"trap":"old-source","b":null,"why":"2024 is not very old. The problem is in the small print."},{"right":false,"trap":"small-sample","b":null,"why":"300 people over two years is a fair size. Read the small print instead."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'When the people who pay for research sell the product, they gain from a ''no link'' result. That is a vested interest.');
insert into public.items (id, block, demand, options, explain) values ('e4-zap-01', 'E4', 0, '[{"right":false,"trap":"small-sample","b":null,"why":"We don''t know how many students were asked. 9 out of 10 could mean just 10 students."},{"right":false,"trap":"small-sample","b":null,"why":"The company printed this in its own advert. We can''t check who the students were."},{"right":false,"trap":"claim-no-evidence","b":null,"why":"Taste can matter, but that is not the problem here. Ask how this number was found."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, '10 students at the company''s own camp is a tiny, chosen group. It tells us almost nothing about all students.');
insert into public.items (id, block, demand, options, explain) values ('e4-compare-01', 'E4', 1, '[{"right":false,"trap":"anecdote-as-proof","b":null,"why":"This is one person''s story, and she is selling something."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"wrong-group","b":null,"why":"This study was about adults, not teens, and a drinks group paid for it."},{"right":false,"trap":"vested-interest-missed","b":null,"why":"A company tested its own drink. It wants to sell, so it is not neutral."}]'::jsonb, 'The survey is large, recent, about teenagers on the island and made by a body that sells nothing.');
insert into public.items (id, block, demand, options, explain) values ('e4-study-01', 'E4', 2, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"all-or-nothing","b":null,"why":"Studies are not always wrong. This one just can''t answer this question."},{"right":false,"trap":"wrong-group","b":null,"why":"It is a lot of people, but check what kind of people they were."},{"right":false,"trap":"all-or-nothing","b":null,"why":"A study only tells you about the people it studied. Check who was in it."}]'::jsonb, 'Evidence about adults may not apply to children, and the funding gives a reason to doubt it.');
insert into public.items (id, block, demand, options, explain) values ('e5-arg-01', 'E5', 0, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"claim-no-evidence","b":null,"why":"Short is easy to remember, but B gives no evidence at all."},{"right":false,"trap":"emotive-hook","b":null,"why":"Sounding sure is not the same as having evidence. ''Everyone knows it'' proves nothing."},{"right":false,"trap":"claim-no-evidence","b":"E4","why":"Wanting the same thing does not make them equal. Look at what each one uses as support."}]'::jsonb, 'A has a claim, a reason and evidence from a credible source. B only has a claim and emotive words.');
insert into public.items (id, block, demand, options, explain) values ('e5-arg-02', 'E5', 1, '[{"right":false,"trap":"claim-no-evidence","b":null,"why":"It does make a claim: ''A ban won''t work.''"},{"right":false,"trap":"claim-no-evidence","b":null,"why":"It does give a reason: students will buy drinks outside school."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"claim-no-evidence","b":null,"why":"A strong argument needs a claim, a reason and one more thing. Which part is missing?"}]'::jsonb, 'Claim: a ban won''t work. Reason: students buy outside. Missing: evidence, such as what happened in other schools.');
insert into public.items (id, block, demand, options, explain) values ('e5-arg-03', 'E5', 2, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"correlation-cause","b":null,"why":"The survey shows a pattern. Does a pattern prove something is the ONLY cause?"},{"right":false,"trap":"old-source","b":null,"why":"2025 is recent. The age of the survey is not the problem."},{"right":false,"trap":"wrong-group","b":null,"why":"The survey asked students aged 11 to 16, not adults."}]'::jsonb, 'Other things, like brushing and sweets, also cause decay. A link shows they happen together, not that one is the only cause.');
insert into public.items (id, block, demand, options, explain) values ('r2-fizz-02', 'R2', 0, '[{"right":false,"trap":"yes-no-question","b":null,"why":"This starts with Is, so it can be answered with just yes or no."},{"right":false,"trap":"yes-no-question","b":null,"why":"This is far too big for one island to research, and it is a yes or no question."},{"right":false,"trap":"vague-question","b":null,"why":"This is too vague. Which people? Which drinks? Where?"},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, '"Why do students on Harvest Key choose sugary drinks?" names the place and the people and needs research. Questions starting with Is or Should can be answered yes or no, and "What do people think about drinks?" is far too broad.');
insert into public.items (id, block, demand, options, explain) values ('r2-fizz-03', 'R2', 1, '[{"right":false,"trap":"yes-no-question","b":null,"why":"It is more focused, but it still starts with Are, so the answer is just yes or no."},{"right":false,"trap":"yes-no-question","b":null,"why":"''Really, really'' and ''the whole world'' make it bigger, not better. It is still yes or no."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"vague-question","b":null,"why":"This is not about the issue at all, and it needs no research."}]'::jsonb, 'Starting with "To what extent" turns a yes/no question into one you must research. Adding detail to a question that starts with Are still leaves a yes/no question.');
insert into public.items (id, block, demand, options, explain) values ('e1-zap-02', 'E1', 1, '[{"right":false,"trap":"author-not-checked","b":null,"why":"Look at the advert''s name. A school did not make it."},{"right":false,"trap":"author-not-checked","b":null,"why":"No doctors are named in the advert. Who is selling the drink?"},{"right":false,"trap":"vested-interest-missed","b":null,"why":"Students did not make this advert. Who makes money if you believe it?"},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'ZapFizz Drinks Ltd made it. The more people believe the advert, the more cans they sell, so they have a vested interest.');
insert into public.items (id, block, demand, options, explain) values ('e1-zap-03', 'E1', 2, '[{"right":false,"trap":"vested-interest-missed","b":null,"why":"Adverts can stretch the truth. Being printed does not make it true."},{"right":false,"trap":"small-sample","b":null,"why":"We don''t know who those students were, and liking the taste says nothing about tests."},{"right":false,"trap":"claim-no-evidence","b":null,"why":"Not every fizzy drink makes you sleepy. That is a new claim with no evidence."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'Advice from someone who sells the product needs checking. The advert gives no evidence that the drink helps in tests.');
insert into public.items (id, block, demand, options, explain) values ('e3-lina-02', 'E3', 1, '[{"right":false,"trap":"author-not-checked","b":null,"why":"The post does not mention any doctor."},{"right":false,"trap":"emotive-hook","b":null,"why":"Capital letters do not check anything. Anyone can type in capitals."},{"right":false,"trap":"claim-no-evidence","b":null,"why":"Her post has no scientific results. It is only her own story."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'Capitals make a claim feel exciting. They add no evidence, and she wants you to buy her plan.');
insert into public.items (id, block, demand, options, explain) values ('e3-lina-03', 'E3', 2, '[{"right":false,"trap":"anecdote-as-proof","b":null,"why":"She is selling a plan, so her post is not balanced."},{"right":false,"trap":"author-not-checked","b":null,"why":"Lots of followers does not make someone an expert."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"all-or-nothing","b":null,"why":"Social media can have true facts. We just need to check them."}]'::jsonb, 'The post shows one side, uses fear and capitals, and ends with an advert. Followers are not the same as expertise.');
insert into public.items (id, block, demand, options, explain) values ('e2-news-02', 'E2', 1, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"old-source","b":null,"why":"Facts can change over time. What was true then may not be true now."},{"right":false,"trap":"author-not-checked","b":null,"why":"A big name does not tell you if the facts are still true."},{"right":false,"trap":"claim-no-evidence","b":null,"why":"That would not help you check the article at all."}]'::jsonb, 'Sales change over time. A fact from 2009 may not be true now, so check for something recent.');
insert into public.items (id, block, demand, options, explain) values ('e2-news-03', 'E2', 2, '[{"right":false,"trap":"old-source","b":null,"why":"Another 2009 article is just as old."},{"right":false,"trap":"anecdote-as-proof","b":null,"why":"One person''s memory of 2009 is still old, and it is only one view."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"old-source","b":null,"why":"Sharing an old article again does not make the facts new."}]'::jsonb, 'A report from this year answers a question about now. Re-sharing an old article doesn''t update it.');
insert into public.items (id, block, demand, options, explain) values ('e1-report-02', 'E1', 0, '[{"right":false,"trap":"author-not-checked","b":null,"why":"That is Lina''s product, not the Health Service''s idea."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"author-not-checked","b":null,"why":"A Health Service would not want that. Read the last line of the report."},{"right":false,"trap":"claim-no-evidence","b":null,"why":"The report never says that. Read the last line again."}]'::jsonb, 'The report ends by suggesting free water at school. Its purpose is students'' health, not selling a product.');
insert into public.items (id, block, demand, options, explain) values ('e1-report-03', 'E1', 2, '[{"right":false,"trap":"claim-no-evidence","b":null,"why":"Drinks companies can do surveys. Think about what they would want the results to say."},{"right":false,"trap":"all-or-nothing","b":null,"why":"Health workers can make mistakes too. Think about what each group wants people to believe."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"all-or-nothing","b":null,"why":"A longer report is not always a more careful one."}]'::jsonb, 'The Health Service doesn''t sell drinks, so it has no money reason to want one answer. That is not the same as never making mistakes.');
insert into public.items (id, block, demand, options, explain) values ('e3-study-02', 'E3', 1, '[{"right":false,"trap":"vested-interest-missed","b":null,"why":"Studies cost money, and someone pays. Read the small print."},{"right":false,"trap":"author-not-checked","b":null,"why":"People who take part in a study don''t usually pay for it."},{"right":false,"trap":"author-not-checked","b":null,"why":"Read the small print again. The Health Service did not pay."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'The soft drinks makers paid. Always look for who paid, because they may want a certain result.');
insert into public.items (id, block, demand, options, explain) values ('e3-study-03', 'E3', 2, '[{"right":false,"trap":"all-or-nothing","b":null,"why":"Funding does not make every word false. Ignoring all of it goes too far."},{"right":false,"trap":"wrong-group","b":null,"why":"The study was about adults. It cannot tell us about children."},{"right":false,"trap":"vested-interest-missed","b":null,"why":"Taking a long time does not remove bias. Read the small print."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'Funding by drink makers is a reason for caution, not proof it is false. Check it against sources with no vested interest.');
insert into public.items (id, block, demand, options, explain) values ('e2-nurse-02', 'E2', 1, '[{"right":false,"trap":"old-source","b":null,"why":"2026 is this year. It is not old."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"all-or-nothing","b":null,"why":"She sees many students in her office, so she does know something."},{"right":false,"trap":"author-not-checked","b":null,"why":"There is no sign that a drinks company pays her."}]'::jsonb, 'She says herself that she hasn''t counted. Her view is useful, but without numbers it is weaker evidence.');
insert into public.items (id, block, demand, options, explain) values ('e2-nurse-03', 'E2', 2, '[{"right":false,"trap":"emotive-hook","b":null,"why":"Saying it with more feeling does not add any evidence."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"anecdote-as-proof","b":null,"why":"One more person''s view is still just a view. It is not counted data."},{"right":false,"trap":"all-or-nothing","b":null,"why":"Ignoring the big survey makes your evidence weaker, not stronger."}]'::jsonb, 'Counting cases over time turns an impression into data. One more story or stronger words would not.');
insert into public.items (id, block, demand, options, explain) values ('e4-compare-02', 'E4', 1, '[{"right":false,"trap":"emotive-hook","b":null,"why":"Exciting is not the same as reliable."},{"right":false,"trap":"author-not-checked","b":null,"why":"Lots of followers does not make a post true."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"all-or-nothing","b":null,"why":"Talking about the same topic does not make two sources equally strong."}]'::jsonb, 'The survey looked at thousands of students. Lina''s post is one person''s story, and she is selling something.');
insert into public.items (id, block, demand, options, explain) values ('e4-compare-03', 'E4', 2, '[{"right":false,"trap":"wrong-group","b":null,"why":"The adult study is not about teens, and a drinks group paid for it."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"anecdote-as-proof","b":null,"why":"The advert comes from a company selling its drink. Should it be in the middle?"},{"right":false,"trap":"vested-interest-missed","b":null,"why":"This list is upside down. Which source has the most and fairest evidence?"}]'::jsonb, 'The survey is large and independent. The nurse is useful but uncounted. The advert has a vested interest and a tiny sample.');
insert into public.items (id, block, demand, options, explain) values ('e5-arg-04', 'E5', 0, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"emotive-hook","b":null,"why":"Funny is not the same as convincing. Look for evidence."},{"right":false,"trap":"claim-no-evidence","b":null,"why":"B is a guess about what students think. It has no evidence."},{"right":false,"trap":"all-or-nothing","b":null,"why":"Water at school matters for health. Compare the support each argument gives."}]'::jsonb, 'A gives a claim, a reason and evidence from a credible source. B is an opinion with no evidence.');
insert into public.items (id, block, demand, options, explain) values ('e5-arg-05', 'E5', 1, '[{"right":false,"trap":"claim-no-evidence","b":null,"why":"Giving energy does not mean healthy. Sugar gives energy too."},{"right":false,"trap":"vested-interest-missed","b":null,"why":"The company wants to sell its drink, so its advert is not neutral evidence."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"all-or-nothing","b":null,"why":"Being about the same drink does not make them equal. Which one uses a fact?"}]'::jsonb, 'B uses a checkable fact. A repeats what the seller says, and the seller gains if you believe it.');
insert into public.items (id, block, demand, options, explain) values ('e5-arg-06', 'E5', 1, '[{"right":false,"trap":"anecdote-as-proof","b":null,"why":"One story is still just one case. It does not show a pattern."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"all-or-nothing","b":null,"why":"One person''s view, not counted carefully, does not prove anything."},{"right":false,"trap":"emotive-hook","b":null,"why":"Shouting does not add any evidence."}]'::jsonb, 'The nurse''s view is a start. Counted data that links the drinks to headaches would be real evidence.');
insert into public.items (id, block, demand, options, explain) values ('e5-arg-07', 'E5', 2, '[{"right":false,"trap":"all-or-nothing","b":null,"why":"It is not how one person feels. Where does the number come from?"},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"claim-no-evidence","b":null,"why":"It does not say what anyone should do. It only gives a number."},{"right":false,"trap":"claim-no-evidence","b":null,"why":"It does not use ''because'' or explain why. Look at what kind of sentence it is."}]'::jsonb, 'It is a fact from the Health Service survey, so it is evidence. The claim would be "ban sugary drinks"; a reason would explain why.');
insert into public.items (id, block, demand, options, explain) values ('m1-mode-01', 'M1', 0, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"wrong-audience","b":null,"why":"He doesn''t use apps, so he would never see a post."},{"right":false,"trap":"wrong-audience","b":null,"why":"He isn''t at school, so a poster there won''t reach him."},{"right":false,"trap":"wrong-audience","b":null,"why":"Your class isn''t the audience here. Who needs the news?"}]'::jsonb, 'Choose the mode that reaches your audience. He doesn''t use apps, so speaking to him (on the phone or face to face) works best.');
insert into public.items (id, block, demand, options, explain) values ('m1-gran-02', 'M1', 1, '[{"right":false,"trap":null,"b":null,"why":"She doesn''t ask for anything in the message."},{"right":false,"trap":null,"b":null,"why":"She mentions the distance, but her message is happy, not a complaint."},{"right":false,"trap":null,"b":null,"why":"She isn''t selling anything or asking anyone to buy. Listen to how she feels."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'She is telling her family how she felt. The distance is background; the happy news is the purpose.');
insert into public.items (id, block, demand, options, explain) values ('m1-email-03', 'M1', 2, '[{"right":false,"trap":null,"b":null,"why":"It''s polite, but it never says what the problem is, so she can''t act on it."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"wrong-audience","b":null,"why":"Too casual for the head of an office, and ''always'' isn''t exact."},{"right":false,"trap":"emotive-hook","b":null,"why":"Shouting makes the reader defensive, and there are no facts she can act on."}]'::jsonb, 'An official audience needs a polite greeting, the exact facts and a clear request. That gives her what she needs to act.');
insert into public.items (id, block, demand, options, explain) values ('m2-group-01', 'M2', 0, '[{"right":false,"trap":null,"b":null,"why":"It''s a written message, so noise isn''t the problem."},{"right":false,"trap":null,"b":null,"why":"The words are simple. Everyone understands them. How does it sound?"},{"right":false,"trap":null,"b":null,"why":"The team knows about the slides. Think about how the message feels to read."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'The words are clear, but the tone is angry and blames people in front of everyone. A better message: ''Can we check who is doing each part?''');
insert into public.items (id, block, demand, options, explain) values ('m2-storm-02', 'M2', 1, '[{"right":false,"trap":null,"b":null,"why":"Being boring isn''t the issue. Could this be false?"},{"right":false,"trap":null,"b":null,"why":"It''s short. Look at who wrote it and what it wants you to do."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"emotive-hook","b":null,"why":"Capital letters show strong feeling, not truth."}]'::jsonb, 'Nobody knows who first wrote it, it gives no official source, and it pushes you to share fast. Check the Ferry Office''s own page first.');
insert into public.items (id, block, demand, options, explain) values ('m2-ferry-03', 'M2', 2, '[{"right":false,"trap":null,"b":null,"why":"We don''t know that. Look at the words in the email itself."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"Nothing says the ferry is on time. The problem is how it''s written."},{"right":false,"trap":null,"b":null,"why":"She runs the ferries! Look at the words and how they sound."}]'::jsonb, 'Short forms like ''ur'' and ''lol'' are the wrong language for an official, and ''fix it'' sounds rude. A fix: ''Dear Ms Rocha, the 8am ferry has been late five times this month. Could it be checked, please?''');
insert into public.items (id, block, demand, options, explain) values ('m2-k-04', 'M2', 0, '[{"right":false,"trap":null,"b":null,"why":"Your friend knows the letter. It''s how short and flat it feels."},{"right":false,"trap":null,"b":null,"why":"Nothing in it is false. Think about how it sounds without a face or voice."},{"right":false,"trap":null,"b":null,"why":"A text is fine for a quick reply. It''s how the reply sounds."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'Tone is how a message sounds. Without a face or voice, a very short reply can sound cold. ''Okay! Happy to help 😊'' sends the same answer warmly.');
insert into public.items (id, block, demand, options, explain) values ('m2-slang-05', 'M2', 1, '[{"right":false,"trap":null,"b":null,"why":"She read the messages. The words themselves are the problem."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"Nobody says it is false. She can''t understand what it means."},{"right":false,"trap":null,"b":null,"why":"Nobody is being rude to her. She just can''t understand the words."}]'::jsonb, 'Slang and short forms are a language barrier for anyone who doesn''t know them. Writing it out (''to be honest, the festival was just OK'') lets everyone join in.');
insert into public.items (id, block, demand, options, explain) values ('m2-call-06', 'M2', 2, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"Nobody said the words were hard. Something stopped them listening."},{"right":false,"trap":null,"b":null,"why":"The rules aren''t false. Look at what was happening during the call."},{"right":false,"trap":null,"b":null,"why":"His tone isn''t the problem. What pulled the team''s attention away?"}]'::jsonb, 'Pings and videos are distractions: they pull attention away from the message. Muting notifications and closing other apps removes the barrier.');
insert into public.items (id, block, demand, options, explain) values ('m3-reply-01', 'M3', 0, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"shut-down","b":null,"why":"It shuts the talk down and gives no reason."},{"right":false,"trap":"shut-down","b":null,"why":"It sounds rude and doesn''t answer the point."},{"right":false,"trap":"attack-person","b":null,"why":"This attacks the person, not the idea."}]'::jsonb, '''I see why you think that, but…'' shows you listened, then gives a reason. That keeps the talk going.');
insert into public.items (id, block, demand, options, explain) values ('m3-para-02', 'M3', 1, '[{"right":false,"trap":"not-listening","b":null,"why":"Kai named a problem too. Don''t change their point to match yours."},{"right":false,"trap":"not-listening","b":null,"why":"Kai didn''t say that. Say what was really said, in your own words."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"not-listening","b":null,"why":"Kai never said ban. A paraphrase keeps the speaker''s meaning."}]'::jsonb, 'A good paraphrase keeps both halves of Kai''s point: the good part (news) and the problem (false stories).');
insert into public.items (id, block, demand, options, explain) values ('m3-signs-03', 'M3', 0, '[{"right":false,"trap":"not-listening","b":null,"why":"Interrupting stops them explaining their own point."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"not-listening","b":null,"why":"Your attention is on the phone. They can tell you aren''t really listening."},{"right":false,"trap":"not-listening","b":null,"why":"That''s half listening: waiting to talk, not trying to understand."}]'::jsonb, 'Eye contact, nodding and a question about their point all show full attention. You listen to understand, not just to reply.');
insert into public.items (id, block, demand, options, explain) values ('m3-main-04', 'M3', 1, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"not-listening","b":null,"why":"Price isn''t in his speech. What does he say happens with Ripple?"},{"right":false,"trap":"not-listening","b":null,"why":"He never says ban. Listen for what he actually argues."},{"right":false,"trap":"not-listening","b":null,"why":"He uses the survey to support his point. He doesn''t attack it."}]'::jsonb, 'His point is that Ripple has reduced face-to-face talk. The café example and the survey number both support that one idea.');
insert into public.items (id, block, demand, options, explain) values ('m3-answer-05', 'M3', 2, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"claim-no-evidence","b":null,"why":"It disagrees, but gives no reason or evidence."},{"right":false,"trap":"attack-person","b":null,"why":"That attacks the person, not the idea."},{"right":false,"trap":"off-topic","b":null,"why":"That''s about the speech, not the point he made."}]'::jsonb, 'It paraphrases his point, admits what''s fair, then answers with evidence. That''s a respectful and relevant reply.');
insert into public.items (id, block, demand, options, explain) values ('m3-clarify-06', 'M3', 1, '[{"right":false,"trap":"shut-down","b":null,"why":"It''s rude, and you learn nothing about what he meant."},{"right":false,"trap":"off-topic","b":null,"why":"That''s off the point. Ask about the part that was unclear."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"attack-person","b":null,"why":"That''s a jab at him, not a question about his point."}]'::jsonb, 'A clarifying question names the unclear words and asks what they mean. Then you can answer the real point.');
insert into public.items (id, block, demand, options, explain) values ('t1-plan-01', 'T1', 0, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"unfair-roles","b":null,"why":"You''d repeat the same work and miss the other points."},{"right":false,"trap":"unfair-roles","b":null,"why":"One person gets all the work, and the others learn nothing."},{"right":false,"trap":null,"b":null,"why":"There won''t be enough time to research and rehearse."}]'::jsonb, 'One point each means no repeats and a fair share. Rehearsing together helps the whole team improve.');
insert into public.items (id, block, demand, options, explain) values ('t1-skills-02', 'T1', 1, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"unfair-roles","b":null,"why":"Dev''s skill is finding sources. Give Dev the research."},{"right":false,"trap":null,"b":null,"why":"Your team can decide by looking at each person''s skills."},{"right":false,"trap":"unfair-roles","b":null,"why":"That''s luck, not skills. Match the job to the person."}]'::jsonb, 'Giving roles by skill makes the team stronger: Chi opens, Dev researches, Ben handles the survey numbers and Ana designs the visuals.');
insert into public.items (id, block, demand, options, explain) values ('t1-time-03', 'T1', 2, '[{"right":false,"trap":null,"b":null,"why":"Time problems get worse if the team doesn''t plan for them."},{"right":false,"trap":"unfair-roles","b":null,"why":"Decide together. Minh may still want to do one part."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"unfair-roles","b":null,"why":"Ignoring time makes the plan unfair, and the work may be rushed."}]'::jsonb, 'Fair teams look at the time each person has. Talking with Minh and moving one job keeps the plan fair and on time.');
insert into public.items (id, block, demand, options, explain) values ('t2-argue-01', 'T2', 0, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"unfair-roles","b":null,"why":"That splits the team instead of solving the problem."},{"right":false,"trap":null,"b":null,"why":"Loud isn''t the same as right, and quieter ideas get lost."},{"right":false,"trap":null,"b":null,"why":"The disagreement stays, and the work stops."}]'::jsonb, 'Listening to both reasons and deciding together solves the disagreement and keeps everyone working.');
insert into public.items (id, block, demand, options, explain) values ('t2-quiet-02', 'T2', 1, '[{"right":false,"trap":null,"b":null,"why":"Mina''s ideas get lost, and she may stop trying."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"attack-person","b":null,"why":"That attacks Leo. Guide the turns instead."},{"right":false,"trap":null,"b":null,"why":"That blames Mina. The team needs to make space for her."}]'::jsonb, 'Giving turns encourages quieter members to join in, without blaming anyone.');
insert into public.items (id, block, demand, options, explain) values ('t2-chat-03', 'T2', 2, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"Leaving doesn''t fix the work, and the team loses you."},{"right":false,"trap":"attack-person","b":null,"why":"Blaming back makes the argument bigger."},{"right":false,"trap":null,"b":null,"why":"The problem stays, and the team keeps arguing."}]'::jsonb, 'Checking who is doing each part, and offering help, turns blame into a plan.');
insert into public.items (id, block, demand, options, explain) values ('m4-evid-01', 'M4', 0, '[{"right":false,"trap":"claim-no-evidence","b":null,"why":"''Everyone knows'' is not evidence. Where is it from?"},{"right":false,"trap":"anecdote-as-proof","b":null,"why":"One person''s opinion isn''t strong evidence for everyone."},{"right":false,"trap":"off-topic","b":null,"why":"That''s about the logo, not families staying in touch."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'A number from a named survey is evidence: it is about families, and the audience can check where it came from.');
insert into public.items (id, block, demand, options, explain) values ('m4-link-02', 'M4', 1, '[{"right":false,"trap":"off-topic","b":null,"why":"That adds a new idea. A Link connects back to the motion."},{"right":false,"trap":null,"b":null,"why":"That''s the Evidence step. The Link goes back to the motion."},{"right":false,"trap":null,"b":null,"why":"That''s the Point. The Link comes at the end, after the explanation."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'The Link connects your point back to the motion, so the judges see why it matters for your side.');
insert into public.items (id, block, demand, options, explain) values ('m4-explain-03', 'M4', 2, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"off-topic","b":null,"why":"That doesn''t connect to the evidence about families talking."},{"right":false,"trap":"claim-no-evidence","b":null,"why":"That goes far beyond the evidence. Explain what the numbers show."},{"right":false,"trap":null,"b":null,"why":"That just repeats the number. Explain what it means."}]'::jsonb, 'The Explain step says what the evidence shows about the point, and no more.');
insert into public.items (id, block, demand, options, explain, seq, steps) values ('m4-jumble-01', 'M4', 0, '[]'::jsonb, 'Point, Evidence, Explain, Link: each sentence does one job, and the Link takes the judges back to the motion.', array[1, 0, 3, 2]::int[], '["A PEEL paragraph starts with the Point: the one idea you will prove.","Second comes the Evidence for the point, with its source.","Third, Explain what the evidence means.","The last sentence Links back to the motion."]'::jsonb);
insert into public.items (id, block, demand, options, explain, seq, steps) values ('m4-jumble-02', 'M4', 1, '[]'::jsonb, 'The Point names the problem, the Evidence is a real example with its source, the Explain says what it shows, and the Link answers the motion.', array[1, 0, 3, 2]::int[], '["A PEEL paragraph starts with the Point: the one idea you will prove.","Second comes the Evidence for the point, with its source.","Third, Explain what the evidence means.","The last sentence Links back to the motion."]'::jsonb);
insert into public.items (id, block, demand, options, explain, seq, steps) values ('m4-jumble-03', 'M4', 2, '[]'::jsonb, 'Even without signal words, a PEEL paragraph has the same shape: the idea, the proof with its source, what it means, then back to the motion.', array[1, 0, 3, 2]::int[], '["A PEEL paragraph starts with the Point: the one idea you will prove.","Second comes the Evidence for the point, with its source.","Third, Explain what the evidence means.","The last sentence Links back to the motion."]'::jsonb);
insert into public.items (id, block, demand, options, explain) values ('m4-cite-04', 'M4', 0, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"author-not-checked","b":null,"why":"Your audience can''t check ''somewhere''. Name the source."},{"right":false,"trap":"claim-no-evidence","b":null,"why":"Calling it a fact doesn''t show where it came from."},{"right":false,"trap":"author-not-checked","b":null,"why":"Who? Name the source so people can trust it."}]'::jsonb, '''According to…'' names who made the evidence and when, so the audience can trust and check it.');
insert into public.items (id, block, demand, options, explain) values ('m4-side-05', 'M4', 1, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"That helps the other side: it shows Ripple connecting families."},{"right":false,"trap":null,"b":null,"why":"That''s how big the survey was. It doesn''t support either side."},{"right":false,"trap":null,"b":null,"why":"That''s the date, not evidence for a side."}]'::jsonb, 'Less face-to-face talk supports the Opposition. The same survey has evidence for both sides, so read all of it.');
insert into public.items (id, block, demand, options, explain) values ('m4-fair-06', 'M4', 2, '[{"right":false,"trap":null,"b":null,"why":"Too vague. Say what it found and how many people were asked."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"87 of 120 is most, not almost all, and it said every week, not every day."},{"right":false,"trap":"wrong-group","b":null,"why":"It asked 120 students, not everyone, and it didn''t ask if they love it."}]'::jsonb, 'An honest report keeps the exact numbers and says who was asked. Stretching evidence makes your whole speech easier to attack.');
insert into public.items (id, block, demand, options, explain) values ('m5-steps-01', 'M5', 0, '[{"right":false,"trap":"off-topic","b":null,"why":"It doesn''t answer the point the other team made."},{"right":false,"trap":"attack-person","b":null,"why":"That attacks the people, not the idea."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"claim-no-evidence","b":null,"why":"It disagrees, but gives no reason or evidence."}]'::jsonb, 'A strong rebuttal repeats their point, disagrees, gives evidence, then says why it matters.');
insert into public.items (id, block, demand, options, explain) values ('m5-because-02', 'M5', 1, '[{"right":false,"trap":"off-topic","b":null,"why":"Everyone agrees, but it doesn''t show how Ripple can stop it."},{"right":false,"trap":"claim-no-evidence","b":null,"why":"Liking something isn''t a reason the audience can check."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"claim-no-evidence","b":null,"why":"That repeats the disagreement. Give a reason or evidence."}]'::jsonb, 'The Because step gives a reason the audience can check. Official updates show how Ripple can stop false news.');
insert into public.items (id, block, demand, options, explain) values ('m5-strong-03', 'M5', 2, '[{"right":false,"trap":"off-topic","b":null,"why":"Closings sum up. A new point there doesn''t answer theirs."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"The judges heard it. Ignoring their strongest point looks weak."},{"right":false,"trap":"claim-no-evidence","b":null,"why":"It''s the same survey you use. Calling it fake without proof hurts you."}]'::jsonb, 'Admitting what''s fair shows you listened. Then your evidence shows why your side is still stronger.');
insert into public.items (id, block, demand, options, explain, seq, steps) values ('m5-jumble-01', 'M5', 0, '[]'::jsonb, 'They said, However, Because, So: repeat their point, disagree, give evidence, then say why it matters.', array[3, 1, 0, 2]::int[], '["The first sentence repeats the other team''s point, so everyone knows what you are answering (''They said…'').","The second sentence says you disagree, and how (''However…'').","The third sentence gives your reason or evidence (''Because…'').","The last sentence says why it matters for the debate (''So…'')."]'::jsonb);
insert into public.items (id, block, demand, options, explain, seq, steps) values ('m5-jumble-02', 'M5', 1, '[]'::jsonb, 'Same four steps with different words: their claim, your disagreement (''But…''), evidence, and what it means (''This means…'').', array[2, 0, 1, 3]::int[], '["The first sentence repeats the other team''s point, so everyone knows what you are answering (''They said…'').","The second sentence says you disagree, and how (''However…'').","The third sentence gives your reason or evidence (''Because…'').","The last sentence says why it matters for the debate (''So…'')."]'::jsonb);
insert into public.items (id, block, demand, options, explain, seq, steps) values ('m5-jumble-03', 'M5', 2, '[]'::jsonb, 'Without signal words, the four steps still hold: their point, your disagreement, your evidence, and why it matters.', array[2, 1, 3, 0]::int[], '["The first sentence repeats the other team''s point, so everyone knows what you are answering (''They said…'').","The second sentence says you disagree, and how (''However…'').","The third sentence gives your reason or evidence (''Because…'').","The last sentence says why it matters for the debate (''So…'')."]'::jsonb);
insert into public.items (id, block, demand, options, explain) values ('m4-sort-01', 'M4', 0, '[{"right":false,"trap":null,"b":null,"why":"Evidence is a fact or number with a source. Look for one in the sentence."},{"right":false,"trap":null,"b":null,"why":"Explain says what a piece of evidence shows. Is there evidence here to explain?"},{"right":false,"trap":null,"b":null,"why":"A Link takes the audience back to the motion. Does this sentence do that?"},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'Each PEEL sentence does one job. Spotting the job helps you check your own notes have all four.');
insert into public.items (id, block, demand, options, explain) values ('m4-sort-02', 'M4', 1, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"Explain says what a piece of evidence shows. Is there evidence here to explain?"},{"right":false,"trap":null,"b":null,"why":"A Link takes the audience back to the motion. Does this sentence do that?"},{"right":false,"trap":null,"b":null,"why":"A Point names the idea to prove. Does this sentence give a fact, explain, or link back instead?"}]'::jsonb, 'Each PEEL sentence does one job. Spotting the job helps you check your own notes have all four.');
insert into public.items (id, block, demand, options, explain) values ('m4-sort-03', 'M4', 1, '[{"right":false,"trap":null,"b":null,"why":"Evidence is a fact or number with a source. Look for one in the sentence."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"A Link takes the audience back to the motion. Does this sentence do that?"},{"right":false,"trap":null,"b":null,"why":"A Point names the idea to prove. Does this sentence give a fact, explain, or link back instead?"}]'::jsonb, 'Each PEEL sentence does one job. Spotting the job helps you check your own notes have all four.');
insert into public.items (id, block, demand, options, explain) values ('m4-sort-04', 'M4', 0, '[{"right":false,"trap":null,"b":null,"why":"Evidence is a fact or number with a source. Look for one in the sentence."},{"right":false,"trap":null,"b":null,"why":"Explain says what a piece of evidence shows. Is there evidence here to explain?"},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"A Point names the idea to prove. Does this sentence give a fact, explain, or link back instead?"}]'::jsonb, 'Each PEEL sentence does one job. Spotting the job helps you check your own notes have all four.');
insert into public.items (id, block, demand, options, explain) values ('m4-sort-05', 'M4', 2, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"Explain says what a piece of evidence shows. Is there evidence here to explain?"},{"right":false,"trap":null,"b":null,"why":"A Link takes the audience back to the motion. Does this sentence do that?"},{"right":false,"trap":null,"b":null,"why":"A Point names the idea to prove. Does this sentence give a fact, explain, or link back instead?"}]'::jsonb, 'Each PEEL sentence does one job. Spotting the job helps you check your own notes have all four.');
insert into public.items (id, block, demand, options, explain) values ('m4-sort-06', 'M4', 2, '[{"right":false,"trap":null,"b":null,"why":"Evidence is a fact or number with a source. Look for one in the sentence."},{"right":false,"trap":null,"b":null,"why":"Explain says what a piece of evidence shows. Is there evidence here to explain?"},{"right":false,"trap":null,"b":null,"why":"A Link takes the audience back to the motion. Does this sentence do that?"},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'Each PEEL sentence does one job. Spotting the job helps you check your own notes have all four.');
insert into public.items (id, block, demand, options, explain) values ('m6-sort-01', 'M6', 0, '[{"right":false,"trap":null,"b":null,"why":"A clarifying question asks what a speaker meant by something unclear."},{"right":false,"trap":null,"b":null,"why":"A closing sums up why your side is stronger, at the end of the debate."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"A rebuttal answers a point the other team made (''They said…, however…'')."}]'::jsonb, 'Each speech has its own job. Knowing which is which helps you plan who says what, and when.');
insert into public.items (id, block, demand, options, explain) values ('m6-sort-02', 'M6', 0, '[{"right":false,"trap":null,"b":null,"why":"A clarifying question asks what a speaker meant by something unclear."},{"right":false,"trap":null,"b":null,"why":"A closing sums up why your side is stronger, at the end of the debate."},{"right":false,"trap":null,"b":null,"why":"An opening greets the audience, says your side and previews your points."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'Each speech has its own job. Knowing which is which helps you plan who says what, and when.');
insert into public.items (id, block, demand, options, explain) values ('m6-sort-03', 'M6', 0, '[{"right":false,"trap":null,"b":null,"why":"A clarifying question asks what a speaker meant by something unclear."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"An opening greets the audience, says your side and previews your points."},{"right":false,"trap":null,"b":null,"why":"A rebuttal answers a point the other team made (''They said…, however…'')."}]'::jsonb, 'Each speech has its own job. Knowing which is which helps you plan who says what, and when.');
