insert into public.items (id, block, demand, options, explain) values ('m6-sort-06', 'M6', 2, '[{"right":false,"trap":null,"b":null,"why":"A clarifying question asks what a speaker meant by something unclear."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"An opening greets the audience, says your side and previews your points."},{"right":false,"trap":null,"b":null,"why":"A rebuttal answers a point the other team made (''They said…, however…'')."}]'::jsonb, 'Each speech has its own job. Knowing which is which helps you plan who says what, and when.');
insert into public.items (id, block, demand, options, explain) values ('m6-sort-07', 'M6', 2, '[{"right":false,"trap":null,"b":null,"why":"A clarifying question asks what a speaker meant by something unclear."},{"right":false,"trap":null,"b":null,"why":"A closing sums up why your side is stronger, at the end of the debate."},{"right":false,"trap":null,"b":null,"why":"An opening greets the audience, says your side and previews your points."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'Each speech has its own job. Knowing which is which helps you plan who says what, and when.');
insert into public.items (id, block, demand, options, explain, seq, steps) values ('m6-jumble-01', 'M6', 0, '[]'::jsonb, 'An opening greets the audience, states the motion and your side, then previews your points in order.', array[1, 3, 0, 2]::int[], '["An opening starts by greeting the audience.","Next, state the motion and which side your team is on.","Then preview your points in order, starting with the first.","The preview ends with your last point."]'::jsonb);
insert into public.items (id, block, demand, options, explain, seq, steps) values ('m6-jumble-02', 'M6', 1, '[]'::jsonb, 'A closing signals the end, sums up your best points, answers their strongest point, and finishes with why you should win.', array[3, 0, 2, 1]::int[], '["A closing starts by signalling the end (''To conclude…'').","Then sum up your best points. No new points in a closing.","Next, answer the other side''s strongest point.","Finish strongly: tell the audience why your side should win."]'::jsonb);
insert into public.items (id, block, demand, options, explain, seq, steps) values ('m6-jumble-03', 'M6', 2, '[]'::jsonb, 'Even the Opposition opens the same way: greet, say the motion and your side, then preview your points in order.', array[2, 3, 0, 1]::int[], '["An opening starts by greeting the audience.","Next, state the motion and which side your team is on.","Then preview your points in order, starting with the first.","The preview ends with your last point."]'::jsonb);
insert into public.items (id, block, demand, options, explain) values ('r2-ember-01', 'R2', 0, '[{"right":false,"trap":"yes-no-question","b":null,"why":"This starts with Are, so it can be answered yes or no. It doesn''t say where or who."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"vague-question","b":null,"why":"This is one small number from one day. It''s too narrow to explain the issue."},{"right":false,"trap":"vague-question","b":null,"why":"One quick search answers this. It isn''t about a sustainability issue."}]'::jsonb, 'The best question starts with How, names the place, the people and the issue, and needs research and evidence to answer.');
insert into public.items (id, block, demand, options, explain) values ('r2-ember-02', 'R2', 1, '[{"right":false,"trap":"yes-no-question","b":null,"why":"This starts with Do, so it''s yes or no. Liking tea isn''t the sustainability issue."},{"right":false,"trap":"yes-no-question","b":null,"why":"This starts with Should, so the answer is just yes or no, and it is far too big."},{"right":false,"trap":"vague-question","b":null,"why":"This is far too broad. Which resource? Which place?"},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, '''Why do so few cups get recycled?'' is focused on one resource and one place, and you need evidence to answer it.');
insert into public.items (id, block, demand, options, explain) values ('r2-ember-03', 'R2', 2, '[{"right":false,"trap":"yes-no-question","b":null,"why":"This is bigger, not better, and it can still be answered with yes or no."},{"right":false,"trap":"yes-no-question","b":null,"why":"Adding ''really very'' doesn''t help. It still starts with Is, so the answer is yes or no."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"vague-question","b":null,"why":"This needs no research and says nothing about the cups'' impact."}]'::jsonb, '''To what extent'' asks how much, so you must weigh evidence. It also names one resource (cups) and one place.');
insert into public.items (id, block, demand, options, explain) values ('l1-stage-01', 'L1', 0, '[{"right":false,"trap":null,"b":null,"why":"End of life is what happens after use: reuse, recycle or rubbish."},{"right":false,"trap":null,"b":null,"why":"Make is when a factory turns materials into the product. Has the oil reached a factory yet?"},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"Use is when people drink from the cup. Nobody has a cup yet."}]'::jsonb, 'The origin is where the material comes from. Plastic cups start as oil taken from the ground.');
insert into public.items (id, block, demand, options, explain) values ('l1-renew-02', 'L1', 1, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"Rain refills water, so it is renewable, though it can still be overused."},{"right":false,"trap":null,"b":null,"why":"Sunlight arrives again every day, so it is renewable."},{"right":false,"trap":null,"b":null,"why":"Tea plants grow again each year, so tea is renewable if farms are cared for."}]'::jsonb, 'Oil takes millions of years to form, so it is non-renewable. Tea, sunlight and rain can be replaced by nature.');
insert into public.items (id, block, demand, options, explain) values ('l1-end-03', 'L1', 2, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"The factory isn''t in this report. Look at what the trucks collect."},{"right":false,"trap":null,"b":null,"why":"The report doesn''t mention oil or where the plastic comes from."},{"right":false,"trap":null,"b":null,"why":"It counts cups collected as rubbish, not drinks being bought."}]'::jsonb, 'The report is about cups after use: collected, recycled or sent to landfill. That''s the end of the life cycle.');
insert into public.items (id, block, demand, options, explain) values ('n1-need-01', 'N1', 0, '[{"right":false,"trap":null,"b":null,"why":"It''s fun, but you can live safely without it."},{"right":false,"trap":null,"b":null,"why":"Tea is nice, but you could live without it. That makes it a want."},{"right":false,"trap":null,"b":null,"why":"A phone case is useful, but nobody needs one to live safely."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'You can''t live without clean water, so it is a need. The others make life easier or more fun, so they are wants.');
insert into public.items (id, block, demand, options, explain) values ('n1-trade-02', 'N1', 1, '[{"right":false,"trap":null,"b":null,"why":"This is an opinion with no real reason, and it doesn''t say what you gained."},{"right":false,"trap":null,"b":null,"why":"This gives the choice but not what you gave up. A trade-off names both."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"There''s no reason and no trade-off, so others can''t understand your choice."}]'::jsonb, 'A strong trade-off sentence says what you chose, what you gave up, why, and what it cost you.');
insert into public.items (id, block, demand, options, explain) values ('n1-agree-03', 'N1', 2, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"Water is a need. Giving up a need to keep two wants is a poor trade-off."},{"right":false,"trap":"shut-down","b":null,"why":"Leaving it empty doesn''t finish the task. The team still needs to agree."},{"right":false,"trap":"unfair-roles","b":null,"why":"Then only one voice counts. Everyone in the team should be heard."}]'::jsonb, 'Hearing each side''s reasons, then deciding together, is fair and helps the team reach a shared outcome.');
insert into public.items (id, block, demand, options, explain) values ('t1-ember-01', 'T1', 0, '[{"right":false,"trap":null,"b":null,"why":"The presentation must have at least one chart, so someone has to plan it."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"The Designer makes the slides clear and consistent, not the statistics."},{"right":false,"trap":null,"b":null,"why":"The Leader keeps the team on task and on time, and makes sure everyone is heard."}]'::jsonb, 'The Data analyst finds the statistics and plans the chart. Everyone still writes and presents one section.');
insert into public.items (id, block, demand, options, explain) values ('t1-ember-02', 'T1', 1, '[{"right":false,"trap":null,"b":null,"why":"Two leaders can pull the team in different directions."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"unfair-roles","b":null,"why":"Everyone must research, write and present one section. Nobody just watches."},{"right":false,"trap":null,"b":null,"why":"The teacher checks the work, but each student belongs to the team''s work."}]'::jsonb, 'In a team of five, two people share the Researcher role, because finding and checking sources is a big job.');
insert into public.items (id, block, demand, options, explain) values ('t1-ember-03', 'T1', 2, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"unfair-roles","b":null,"why":"Every student, whatever their role, writes a section, and that needs research."},{"right":false,"trap":"unfair-roles","b":null,"why":"That''s unfair the other way. Each person researches their own section."},{"right":false,"trap":null,"b":null,"why":"Swapping roles doesn''t fix it. The rule is the same for every role."}]'::jsonb, 'Roles add a job; they don''t replace the shared work. Everyone researches, writes and presents one section.');
insert into public.items (id, block, demand, options, explain) values ('i1-sort-01', 'I1', 0, '[{"right":false,"trap":null,"b":null,"why":"Global means the whole world. This is only about one person."},{"right":false,"trap":null,"b":null,"why":"Local means a city or a country. This is about one person''s own life."},{"right":false,"trap":null,"b":null,"why":"Cups that are thrown away go somewhere, so there is an impact."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'It is about one person''s own habits, so it is a personal impact.');
insert into public.items (id, block, demand, options, explain) values ('i1-sort-02', 'I1', 1, '[{"right":false,"trap":null,"b":null,"why":"It only counts cups on Ember Reef, not around the world."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"Collected cups mostly go to landfill. That is still an impact."},{"right":false,"trap":null,"b":null,"why":"The report counts cups from the whole island, not from one family."}]'::jsonb, 'The report is about one island''s rubbish, so it shows a local impact. In your project, local means Vietnam or your city.');
insert into public.items (id, block, demand, options, explain) values ('i1-sort-03', 'I1', 2, '[{"right":false,"trap":null,"b":null,"why":"That''s about one school on the island, so it''s a local impact."},{"right":false,"trap":null,"b":null,"why":"That''s about you and your money, so it''s a personal impact."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"That''s about one island''s beach, so it''s a local impact."}]'::jsonb, 'Plastic from many countries ends up in the world''s oceans, so it is a global impact.');
insert into public.items (id, block, demand, options, explain) values ('e1-ember-01', 'E1', 0, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"author-not-checked","b":null,"why":"Check the line at the bottom. There''s no research in this advert."},{"right":false,"trap":"author-not-checked","b":null,"why":"Read the line at the bottom. It wasn''t made by students."},{"right":false,"trap":"author-not-checked","b":null,"why":"The Waste Office didn''t make this. Read who it''s by."}]'::jsonb, 'PearlPop Tea made it to sell drinks (''Buy five drinks''). A company that sells cups may only show the good side.');
insert into public.items (id, block, demand, options, explain) values ('e1-ember-02', 'E1', 1, '[{"right":false,"trap":null,"b":null,"why":"The topic is fine. The problem is who is behind the post."},{"right":false,"trap":"old-source","b":null,"why":"It was posted in 2026, so the date isn''t the problem here."},{"right":false,"trap":"emotive-hook","b":null,"why":"Emojis don''t make a post true or false. Check who is behind it."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'It is sponsored by PearlPop Tea, the shop that sells the cups. A paid post has a reason to say cups are fine, and gives no evidence.');
insert into public.items (id, block, demand, options, explain) values ('e1-ember-03', 'E1', 2, '[{"right":false,"trap":null,"b":null,"why":"It''s a serious report with quotes from experts, not a joke."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"emotive-hook","b":null,"why":"It doesn''t blame students. It reports what a scientist and the factory say."},{"right":false,"trap":"vested-interest-missed","b":null,"why":"The reporter isn''t selling anything. A factory manager is quoted, but he isn''t the author."}]'::jsonb, 'A reporter wrote it to inform. It quotes a scientist and the factory manager, so it shows more than one side: that''s balance.');
insert into public.items (id, block, demand, options, explain) values ('e2-ember-01', 'E2', 0, '[{"right":false,"trap":"old-source","b":null,"why":"Pictures don''t make a source more reliable. Check the date."},{"right":false,"trap":"old-source","b":null,"why":"The topic fits your project. Look at the date."},{"right":false,"trap":"old-source","b":null,"why":"Short sources can still be useful. Check when it was made."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'It is from 2009, so it may no longer be true. It was also made to attract tourists, not to give data.');
insert into public.items (id, block, demand, options, explain) values ('e2-ember-02', 'E2', 1, '[{"right":false,"trap":"all-or-nothing","b":null,"why":"That''s all or nothing. A council counting its own trucks'' rubbish is a strong source."},{"right":false,"trap":null,"b":null,"why":"Boring isn''t a reason to distrust. Ask who made it and why."},{"right":false,"trap":"old-source","b":null,"why":"The report is from 2026, so the date isn''t the problem."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'The Waste Office counts the cups itself, the report is recent, and it isn''t selling anything, so it earns a high trust score.');
insert into public.items (id, block, demand, options, explain) values ('e2-ember-03', 'E2', 2, '[{"right":false,"trap":"vested-interest-missed","b":null,"why":"PearlPop wants to sell drinks, so it may only show the good side."},{"right":false,"trap":"vested-interest-missed","b":null,"why":"The post was paid for by PearlPop and gives no evidence."},{"right":false,"trap":"old-source","b":null,"why":"It''s from 2009, and it was made to attract visitors."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'The Waste Office counts the cups itself, is recent and isn''t selling anything. The others want to sell, were paid, or are out of date.');
insert into public.items (id, block, demand, options, explain) values ('r4-ref-01', 'R4', 0, '[{"right":false,"trap":null,"b":null,"why":"This has no author, date or link, so nobody can find it again."},{"right":false,"trap":null,"b":null,"why":"Google is a search tool, not the source. Name who made it."},{"right":false,"trap":"chatbot-source","b":null,"why":"A chatbot is not a source. Find the fact in a real source."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'A full reference names the author, the title, the date and the link, so anyone can find and check it.');
insert into public.items (id, block, demand, options, explain) values ('r4-chat-02', 'R4', 1, '[{"right":false,"trap":"chatbot-source","b":null,"why":"A chatbot is not a source. It can even make numbers up."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"changed-data","b":null,"why":"Changing data is dishonest. Give each number exactly as the source gives it."},{"right":false,"trap":"chatbot-source","b":null,"why":"Chatbots can be wrong, and the project rules say a chatbot is not a source."}]'::jsonb, 'AI can help you understand, but a chatbot is not a source. Find the number in a real source, like the Waste Office report, and cite that.');
insert into public.items (id, block, demand, options, explain) values ('r4-fact-03', 'R4', 2, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"wrong-group","b":null,"why":"The survey says it did not ask adults."},{"right":false,"trap":"wrong-group","b":null,"why":"It asked 150 students if they buy tea, not if they love it, and not all students."},{"right":false,"trap":"claim-no-evidence","b":null,"why":"The survey says nothing about health. Record what it actually found."}]'::jsonb, 'A key fact says exactly what the source found, about the people it asked. Keep the numbers as the source gives them.');
insert into public.items (id, block, demand, options, explain) values ('d1-chart-01', 'D1', 0, '[{"right":false,"trap":"wrong-chart","b":null,"why":"A line graph shows change over time. Is your data about time?"},{"right":false,"trap":"wrong-chart","b":null,"why":"A map shows where things are, not parts of a whole."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"wrong-chart","b":null,"why":"A table suits lots of exact numbers. You have parts of one whole."}]'::jsonb, 'A pie chart shows the parts of a whole, like recycled cups compared with all the cups collected.');
insert into public.items (id, block, demand, options, explain) values ('d1-chart-02', 'D1', 1, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"wrong-chart","b":null,"why":"A life cycle diagram shows stages, not amounts."},{"right":false,"trap":"wrong-chart","b":null,"why":"A line graph shows change over time. You''re comparing three amounts."},{"right":false,"trap":"wrong-chart","b":null,"why":"A pie chart shows parts of one whole, not three separate amounts."}]'::jsonb, 'A bar chart compares amounts, so the three schools can be seen side by side.');
insert into public.items (id, block, demand, options, explain) values ('d1-sent-03', 'D1', 2, '[{"right":false,"trap":"changed-data","b":null,"why":"Check the number. Give it exactly as the source gives it."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"There''s no source or year, and it doesn''t explain what the number shows."},{"right":false,"trap":null,"b":null,"why":"''Lots'' isn''t the number the source gives, and ''everyone must stop'' goes too far."}]'::jsonb, 'A strong evidence sentence names the source and year, gives the number exactly, and explains what it shows.');
insert into public.items (id, block, demand, options, explain, seq, steps) values ('m4-ember-01', 'M4', 0, '[]'::jsonb, 'A section slide gives one idea, proves it with a sourced fact, explains it, and links to what the audience should do.', array[1, 0, 3, 2]::int[], '["A section starts with your Point: the one idea this slide proves.","Next comes the Evidence: a fact or number with its source and year.","Then Explain what the evidence shows (''This shows that…'').","Last, Link back to your recommendation: what should the audience do?"]'::jsonb);
insert into public.items (id, block, demand, options, explain, seq, steps) values ('m4-ember-02', 'M4', 1, '[]'::jsonb, 'Even a slide about producers follows the same shape: point, sourced evidence, what it means, then the recommendation.', array[0, 2, 3, 1]::int[], '["A section starts with your Point: the one idea this slide proves.","Next comes the Evidence: a fact or number with its source and year.","Then Explain what the evidence shows (''This shows that…'').","Last, Link back to your recommendation: what should the audience do?"]'::jsonb);
insert into public.items (id, block, demand, options, explain, seq, steps) values ('m4-ember-03', 'M4', 2, '[]'::jsonb, 'Without signal words the shape is the same: the idea, the proof with its source, what it means, then who should act.', array[3, 0, 1, 2]::int[], '["A section starts with your Point: the one idea this slide proves.","Next comes the Evidence: a fact or number with its source and year.","Then Explain what the evidence shows (''This shows that…'').","Last, Link back to your recommendation: what should the audience do?"]'::jsonb);
insert into public.items (id, block, demand, options, explain) values ('p1-voice-01', 'P1', 0, '[{"right":false,"trap":"one-perspective","b":null,"why":"Consumers buy and use the product. Mai grows the tea."},{"right":false,"trap":"one-perspective","b":null,"why":"Manufacturers turn materials into products in factories. Mai grows the leaves."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"one-perspective","b":null,"why":"Waste authorities deal with rubbish. Mai works at the start of the life cycle."}]'::jsonb, 'Mai grows the tea, so she is a producer. Her view shows that using less can hurt people at the start of the life cycle.');
insert into public.items (id, block, demand, options, explain) values ('p1-missing-02', 'P1', 1, '[{"right":false,"trap":"one-perspective","b":null,"why":"Producers are already in. Who handles the rubbish?"},{"right":false,"trap":"one-perspective","b":null,"why":"Consumers are already in. Who deals with the cups after use?"},{"right":false,"trap":"one-perspective","b":null,"why":"Manufacturers are already in. Think about the end of the life cycle."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'The team has producers, a manufacturer and consumers. The Waste Office would add the view from the end of the life cycle.');
insert into public.items (id, block, demand, options, explain) values ('p1-act-03', 'P1', 2, '[{"right":false,"trap":null,"b":null,"why":"This is far too extreme, and ''cups are bad'' gives no evidence."},{"right":false,"trap":null,"b":null,"why":"That claim comes from a paid post with no evidence behind it."},{"right":false,"trap":null,"b":null,"why":"Guilt isn''t an action. Who should do what, and what evidence shows it works?"},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'It names who should act (shops), what to do (a discount), and gives evidence from the survey that students would take part.');
insert into public.items (id, block, demand, options, explain) values ('g1-fb-01', 'G1', 0, '[{"right":false,"trap":"vague-feedback","b":null,"why":"This isn''t kind or specific, and gives no way to improve."},{"right":false,"trap":"vague-feedback","b":null,"why":"Kind, but not specific. What exactly was good?"},{"right":false,"trap":"vague-feedback","b":null,"why":"Which stuff? The team can''t act on this."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'It names exactly what worked (the pie chart) and why (it made the problem clear), so the team knows what to keep.');
insert into public.items (id, block, demand, options, explain) values ('g1-fb-02', 'G1', 1, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"changed-data","b":null,"why":"Changing data is dishonest. The problem is the missing sources."},{"right":false,"trap":null,"b":null,"why":"Data makes an argument stronger. Keep it and add the sources."},{"right":false,"trap":"attack-person","b":null,"why":"This sounds like an attack and gives them no way to fix it."}]'::jsonb, 'A useful suggestion is specific and can be acted on: add the source and year for every statistic.');
insert into public.items (id, block, demand, options, explain) values ('g1-fb-03', 'G1', 2, '[{"right":false,"trap":null,"b":null,"why":"Agreeing isn''t judging. Say what the evidence does well or badly."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":null,"b":null,"why":"That''s about delivery. The question asks about the evidence."},{"right":false,"trap":"vague-feedback","b":null,"why":"Colour isn''t evidence. Judge how the argument uses its data."}]'::jsonb, 'It praises the data and names its limit (who was asked). That helps the team add another source to make the argument stronger.');
insert into public.trust_cards (idx, ok, trap, why) values (0, true, null, 'Expert author, recent data, no product to sell.');
